// §14.2 Aprobacion en vivo: el residente decide desde el correo o Telegram.
//
// Los dos enlaces (urlAprobar, urlRechazar) los construye Spring con el token
// de un solo uso ya hasheado en base. n8n NO los arma ni los firma: solo los
// transporta.
//
// Importante: esos enlaces llevan a una PAGINA DE CONFIRMACION (GET), que no
// decide nada. El boton de esa pagina hace el POST que aplica la decision.
// Es justo por esto: Gmail, Outlook y Telegram pre-cargan los enlaces de un
// mensaje, y con un GET que aprobara ese prefetch quemaria el token y
// decidiria sin que el residente toque nada.

const esperado = $env.PORTERIA_SECRET;
const admin = $env.CORREO_ADMINISTRACION || 'administracion@example.test';
const salida = [];

for (const item of $input.all()) {
  const cabeceras = item.json.headers || {};
  const evento = item.json.body || item.json;

  if (esperado) {
    const recibido = cabeceras['x-porteria-secret'] || cabeceras['X-Porteria-Secret'];
    if (recibido !== esperado) {
      throw new Error('X-Porteria-Secret invalido: evento descartado');
    }
  }

  if (evento.tipo !== 'VISITA_NO_ANUNCIADA') {
    console.log('Tipo que no corresponde a este flujo: ' + evento.tipo);
    continue;
  }

  const d = evento.datos || {};
  const apto = d.apartamento || 'sin apartamento';

  salida.push({
    json: {
      tipo: evento.tipo,
      destinatario: d.correoResidente || admin,
      asunto: d.visitanteNombre + ' pide subir a tu apartamento',
      texto: [
        d.visitanteNombre + ' esta en la porteria del conjunto.',
        'Apartamento: ' + apto + '.',
        d.motivo ? 'Motivo: ' + d.motivo : '',
        d.vigilante ? 'Lo registro el vigilante ' + d.vigilante + '.' : '',
        '',
        'APROBAR:  ' + d.urlAprobar,
        'RECHAZAR: ' + d.urlRechazar,
        '',
        'Tienes hasta ' + d.venceEn + ' para responder.',
        'Si no respondes, la decision queda en manos del vigilante.',
        '',
        'Los enlaces abren una pagina de confirmacion y sirven una sola vez.',
      ].filter(Boolean).join('\n'),
    },
  });
}

return salida;
